-- CivicRaise MVP integrity, citizen review access, and ratification safeguards.
create policy "deliverables backer read" on deliverables for select using (exists (select 1 from contracts c join rfps r on r.id=c.rfp_id where c.id=deliverables.contract_id and exists (select 1 from pledges p where p.campaign_id=r.campaign_id and p.user_id=auth.uid())) or public.is_admin());
create or replace function public.validate_ratification_vote() returns trigger language plpgsql security definer set search_path=public as $$ declare expected bigint; begin select coalesce(sum(amount_cents),0) into expected from public.pledges p join public.ratification_ballots b on b.campaign_id=p.campaign_id where b.id=new.ballot_id and p.user_id=new.user_id; if expected<=0 then raise exception 'Only campaign backers may vote'; end if; new.pledged_cents:=expected; return new; end; $$;
drop trigger if exists ratification_vote_validate on ratification_votes; create trigger ratification_vote_validate before insert or update on ratification_votes for each row execute procedure public.validate_ratification_vote();
